//go:build production

package webui

import (
	"embed"
	"io/fs"
	"net/http"
)

// Generated by the frontend build; not needed by Go tests or development.
//
//go:embed all:dist
var assets embed.FS

func Handler() http.Handler {
	files, err := fs.Sub(assets, "dist")
	if err != nil {
		panic(err)
	}
	return fromFS(files)
}
